/* ===== main.js ===== */
"use strict";

const SQL_WASM_PATH = "js/sql-wasm.wasm";

const SQL_FROM_REGEX = /FROM\s+((?=['"])((["'])(?<g1>[^'"]+))|(?<g2>\w+))/mi;
const SQL_LIMIT_REGEX = /LIMIT\s+(\d+)(?:\s*,\s*(\d+))?/mi;
const SQL_SELECT_REGEX = /SELECT\s+[^;]+\s+FROM\s+/mi;

let db = null;
let lastCachedQueryCount = { select: "", count: 0 };
let loadedTableNames = [];
const editor = ace.edit("sql-editor");
const errorBox = $("#error");
const infoBox = $("#info");
const esc = v => String(v ?? "").replace(/[&<>"']/g, c => ({"&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;"}[c]));
const q = n => `"${String(n).replace(/"/g, '""')}"`;
let SQLPromise = null;
let tableMeta = [];

const selectFormatter = function (item) {
    const i = item.text.lastIndexOf(" (");
    if (i < 1) return item.text;
    return $("<span>").text(item.text.substring(0, i)).append($("<span>").css("opacity", .45).text(item.text.substring(i)));
};

initialize();

function initialize() {
    let fileReaderOpts = {
        readAsDefault: "ArrayBuffer", on: {
            load: function (e) {
                loadDB(e.target.result);
            }
        }
    };

    let toggleFullScreen = function () {
        const container = $("#main-container");
        const resizerExpandIcon = $("#resizer-expand");
        const resizerCollapseIcon = $("#resizer-collapse");

        container.toggleClass("container container-fluid");
        resizerExpandIcon.toggle();
        resizerCollapseIcon.toggle();
    };
    $("#resizer").click(toggleFullScreen);
    $("#sql-editor").keydown(onKeyDown);

    if (typeof FileReader === "undefined" || typeof WebAssembly === "undefined") {
        $("#dropzone, #dropzone-dialog").hide();
        $("#compat-error").toggleClass("d-none", false);
    } else {
        $("#main-container, #dropzone-dialog").fileReaderJS(fileReaderOpts);
    }

    //Initialize editor
    editor.setTheme("ace/theme/chrome");
    editor.renderer.setShowGutter(false);
    editor.renderer.setShowPrintMargin(false);
    editor.renderer.setPadding(20);
    editor.renderer.setScrollMargin(8, 8, 0, 0);
    editor.setHighlightActiveLine(false);
    editor.getSession().setUseWrapMode(true);
    editor.getSession().setUseWorker(false);
    editor.getSession().setMode("ace/mode/sql");
    editor.setOptions({maxLines: 5});
    editor.setFontSize(16);

    $("#table-list").on("click", ".tbl", function () {
        doDefaultSelect($(this).data("name"));
    });
    $("#table-filter").on("input", function () {
        const term = this.value.trim().toLowerCase();
        $("#table-list li").each(function () {
            $(this).toggle($(this).find(".tbl").data("name").toLowerCase().includes(term));
        });
    });

    $(".no-propagate").on("click", function (el) {
        el.stopPropagation();
    });

    //Check url to load remote DB
    $.urlParam = function (name) {
        let results = new RegExp( `[\?&]${name}=([^&#]*)`).exec(window.location.href);
        if (results == null) {
            return null;
        } else {
            return results[1] || 0;
        }
    };
    const loadUrlDB = $.urlParam("url");
    if (loadUrlDB != null) {
        setIsLoading(true);
        const xhr = new XMLHttpRequest();
        xhr.open("GET", decodeURIComponent(loadUrlDB), true);
        xhr.responseType = "arraybuffer";
        xhr.onload = function () {
            if (this.status >= 200 && this.status < 300) {
                loadDB(this.response);
            } else {
                setIsLoading(false);
                window.alert(`Could not load the file (HTTP ${this.status}).`);
            }
        };
        xhr.onerror = function () {
            setIsLoading(false);
            window.alert("Could not load the file. The server must allow cross-origin requests (CORS).");
        };
        xhr.send();
    }
}

function loadDB(arrayBuffer) {
    setIsLoading(true);
    resetTableList();
    lastCachedQueryCount = { select: "", count: 0 };
    tableMeta = [];

    SQLPromise = SQLPromise || initSqlJs({locateFile: () => SQL_WASM_PATH});
    SQLPromise.then(function (SQL) {
        let tables = null;
        try {
            if (db) db.close();
            db = null;
            db = new SQL.Database(new Uint8Array(arrayBuffer));
            tables = db.prepare("SELECT * FROM sqlite_master WHERE type='table' OR type='view' ORDER BY name");
        } catch (ex) {
            if (tables !== null) tables.free();
            if (db) db.close();
            db = null;
            setIsLoading(false);
            window.alert(ex);
            return;
        }

        let firstTableName = null;
        const tableList = $("#tables");

        while (tables.step()) {
            const rowObj = tables.getAsObject();
            const name = rowObj["name"];
            const type = rowObj["type"];
            if (firstTableName === null) firstTableName = name;
            const rowCount = getTableRowsCount(name);
            loadedTableNames.push(name);
            tableMeta.push({name: name, count: rowCount, type: type});
            const tableType = type !== "table" ? `, ${type}` : "";
            tableList.append($("<option>").val(name).text(`${name} (${rowCount} rows${tableType})`));
        }
        tables.free();

        renderTableList();

        if (firstTableName !== null) {
            tableList.val(firstTableName).trigger("change.select2");
            doDefaultSelect(firstTableName);
        } else {
            editor.setValue("", -1);
            $("#data thead tr, #data tbody").empty();
            errorBox.hide();
            infoBox.text("This database has no tables or views.").show();
            setPagerVisible(false);
        }

        $("#output-box").fadeIn();
        $(".nouploadinfo").hide();
        $("#sample-db-link").hide();
        $("body").addClass("loaded");
        setIsLoading(false);
    });
}

function renderTableList() {
    const list = $("#table-list").empty();
    $("#table-filter").val("");
    $("#table-count").text(tableMeta.length);
    tableMeta.forEach(function (t) {
        const meta = t.type === "table" ? t.count : `${t.type} · ${t.count}`;
        const btn = $('<button type="button" class="tbl">').data("name", t.name)
            .append($('<span class="tbl-name">').text(t.name), $('<span class="tbl-meta">').text(meta));
        list.append($("<li>").append(btn));
    });
}

function setActiveTable(name) {
    $("#table-list .tbl").each(function () {
        $(this).toggleClass("active", $(this).data("name") === name);
    });
}

function getTableRowsCount(name) {
    const sel = db.prepare(`SELECT COUNT(*) AS count FROM ${q(name)}`);
    if (sel.step()) {
        const count = sel.getAsObject()["count"];
        sel.free();
        return count;
    } else {
        sel.free();
        return -1;
    }
}

function getQueryRowCount(query) {
    const countQuery = query.replace(SQL_SELECT_REGEX, "SELECT COUNT(*) AS count FROM ").replace(SQL_LIMIT_REGEX, "");
    if (countQuery === query) return -1;
    if (countQuery === lastCachedQueryCount.select) return lastCachedQueryCount.count;

    let sel = null;
    try {
        sel = db.prepare(countQuery);
        const count = sel.step() ? sel.getAsObject()["count"] : -1;
        lastCachedQueryCount = { select: countQuery, count: count };
        return count;
    } catch (ex) {
        return -1;
    } finally {
        if (sel) sel.free();
    }
}

function getTableColumnTypes(tableName) {
    let result = new Map();
    const sel = db.prepare(`PRAGMA table_info(${q(tableName)})`);

    while (sel.step()) {
        const obj = sel.getAsObject();
        let type = obj["type"];
        if (obj["notnull"] === 1) {
            type += " NOT NULL";
        }
        if (obj["pk"] === 1) {
            type += " PRIMARY KEY";
        }
        result.set(obj.name, type);
    }
    sel.free();

    return result;
}

function resetTableList() {
    const tables = $("#tables");
    loadedTableNames = [];
    if (tables.hasClass("select2-hidden-accessible")) tables.select2("destroy");
    tables.off("change");
    tables.empty();
    tables.append("<option></option>");
    tables.select2({
        placeholder: "Select a table",
        theme: "bootstrap-5",
        templateSelection: selectFormatter,
        templateResult: selectFormatter
    });
    tables.on("change", function (e) {
        doDefaultSelect(tables.val());
    });
}

function setIsLoading(isLoading) {
    const dropText = $("#drop-text");
    const loading = $("#drop-loading");
    if (isLoading) {
        dropText.hide();
        loading.toggleClass("d-none", false);
    } else {
        dropText.show();
        loading.toggleClass("d-none", true);
    }
}

function dropzoneClick() {
    $("#dropzone-dialog").val("").click();
}

function doDefaultSelect(name) {
    $("#tables").val(name).trigger("change.select2");
    setActiveTable(name);
    const defaultSelect = `SELECT * FROM ${q(name)} LIMIT 0,30`;
    editor.setValue(defaultSelect, -1);
    renderQuery(defaultSelect);
}

function executeSql() {
    const query = editor.getValue();
    renderQuery(query);
    const name = getTableNameFromQuery(query);
    if (name !== null && loadedTableNames.includes(name)) {
        $("#tables").val(name).trigger("change.select2");
        setActiveTable(name);
    }
}

function getTableNameFromQuery(query) {
    const sqlRegex = SQL_FROM_REGEX.exec(query);
    if (sqlRegex != null) {
        return sqlRegex.groups.g1 ?? sqlRegex.groups.g2;
    } else {
        return null;
    }
}

function parseLimitFromQuery(query) {
    const sqlRegex = SQL_LIMIT_REGEX.exec(query);
    if (sqlRegex != null) {
        let result = { max: 0, offset: 0 };

        if (sqlRegex.length > 2 && typeof sqlRegex[2] !== "undefined") {
            result.offset = parseInt(sqlRegex[1]);
            result.max = parseInt(sqlRegex[2]);
        } else {
            result.offset = 0;
            result.max = parseInt(sqlRegex[1]);
        }

        if (result.max == 0) {
            result.pages = 0;
            result.currentPage = 0;
            return result;
        }

        const queryRowsCount = getQueryRowCount(query);
        if (queryRowsCount != -1) {
            result.pages = Math.ceil(queryRowsCount / result.max);
        }
        result.currentPage = Math.floor(result.offset / result.max) + 1;
        result.rowCount = queryRowsCount;

        return result;
    } else {
        return null;
    }
}

function setPage(el, next) {
    if ($(el).hasClass("disabled")) return;

    const query = editor.getValue();
    const limit = parseLimitFromQuery(query);

    let pageToSet = 0;
    if (typeof next !== "undefined") {
        pageToSet = (next ? limit.currentPage : limit.currentPage - 2);
    } else {
        const page = window.prompt("Go to page");
        if (!isNaN(page) && page >= 1 && page <= limit.pages) {
            pageToSet = page - 1;
        } else {
            return;
        }
    }

    const offset = (pageToSet * limit.max);
    editor.setValue(query.replace(SQL_LIMIT_REGEX, `LIMIT ${offset},${limit.max}`), -1);

    executeSql();
}

function refreshPagination(query) {
    const limit = parseLimitFromQuery(query);
    if (limit !== null && limit.pages > 0) {
        const pager = $("#pager");
        const pagePrev = $("#page-prev");
        const pageNext = $("#page-next");

        pager.attr("title", `Row count: ${limit.rowCount}`);
        bootstrap.Tooltip.getOrCreateInstance("#pager").hide();
        pager.text(limit.currentPage + " / " + limit.pages);

        if (limit.currentPage <= 1) {
            pagePrev.addClass("disabled");
        } else {
            pagePrev.removeClass("disabled");
        }

        if ((limit.currentPage + 1) > limit.pages) {
            pageNext.addClass("disabled");
        } else {
            pageNext.removeClass("disabled");
        }

        setPagerVisible(true);
    } else {
        setPagerVisible(false);
    }
}

function showError(msg) {
    $("#data").hide();
    setPagerVisible(false);
    errorBox.show();
    errorBox.text(msg);
}

function setPagerVisible(visible) {
    $("#bottom-bar").toggleClass("d-none", !visible);
}

function htmlEncode(value) {
    return $("<div/>").text(value).html();
}

function renderQuery(query) {
    const dataBox = $("#data");
    const thead = dataBox.find("thead").find("tr");
    const tbody = dataBox.find("tbody");

    document.querySelectorAll('#data [data-bs-toggle="tooltip"]').forEach(el => {
        const t = bootstrap.Tooltip.getInstance(el);
        if (t) t.dispose();
    });
    thead.empty();
    tbody.empty();
    errorBox.hide();
    infoBox.hide();
    dataBox.show();

    let columnTypes = new Map();
    const tableName = getTableNameFromQuery(query);
    if (tableName != null) {
        columnTypes = getTableColumnTypes(tableName);
    }

    let sel = null;
    try {
        sel = db.prepare(query);
    } catch (ex) {
        if (sel != null) {
            sel.free();
        }
        showError(ex);
        return;
    }

    let isEmptyTable = true;
    const columnNames = sel.getColumnNames();
    for (let i = 0; i < columnNames.length; i++) {
        const columnName = columnNames[i];
        const type = columnTypes.has(columnName) ? columnTypes.get(columnNames[i]) : "";
        thead.append($("<th>").append($("<span>").attr({"data-bs-toggle": "tooltip", title: type}).text(columnName)));
    }

    while (sel.step()) {
        isEmptyTable = false;
        const tr = $('<tr>');
        const s = sel.get();
        for (let i = 0; i < s.length; i++) {
            const columnName = columnNames[i];
            const type = columnTypes.has(columnName) ? columnTypes.get(columnName).toLowerCase() : "";
            if (type === "blob" || type === "blob sub_type binary" || s[i] instanceof Uint8Array) {
                if (s[i] === null) {
                    tr.append(`<td class="is-null"><span title="Blob"></span></td>`);
                } else {
                    renderBlobItem(tr, s[i]);
                }
            } else {
                let value = esc(s[i]);
                const cls = s[i] === null ? "is-null" : (typeof s[i] === "number" ? "num" : "");
                tr.append(`<td class="${cls}"><span title="${value}">${value}</span></td>`);
            }
        }
        tbody.append(tr);
    }
    sel.free();

    if (isEmptyTable) {
        infoBox.text("No data for given select.");
        infoBox.show();
    }

    refreshPagination(query);

    // Enable tooltips
    document.querySelectorAll('#data [data-bs-toggle="tooltip"]')
        .forEach(tooltipTriggerEl => new bootstrap.Tooltip(tooltipTriggerEl));

    dataBox.editableTableWidget();
}

function renderBlobItem(tr, bytes) {
    const td = document.createElement("td");
    const span = document.createElement("span");
    span.title = "Blob";
    const downloadLink = document.createElement("a");
    downloadLink.href = "javascript:void(0)";
    downloadLink.innerText = `Download (${formatBytes(bytes.length)})`;
    downloadLink.onclick = function () {
        saveAs(new Blob([bytes]), "blob");
    };
    span.append(downloadLink);
    td.append(span);
    tr.append(td);
}

function formatBytes(bytes,decimals) {
    if(bytes === 0) return '0 Bytes';
    const k = 1024,
        dm = decimals || 2,
        sizes = ['Bytes', 'KB', 'MB', 'GB', 'TB', 'PB', 'EB', 'ZB', 'YB'],
        i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(dm)) + ' ' + sizes[i];
}

function onKeyDown(e) {
    if ((e.ctrlKey || e.metaKey) && e.key === "Enter") {
        executeSql();
    }
}

function arrayToCsv(data) {
    return data.map(row =>
        row.map(v => v === null || v === undefined ? "" : (v instanceof Uint8Array ? `[BLOB ${formatBytes(v.length)}]` : String(v)))
            .map(v => v.replaceAll('"', '""'))  // escape double quotes
            .map(v => `"${v}"`)  // quote it
            .join(',')  // comma-separated
    ).join('\r\n');  // rows starting on new lines
}

function exportCsvTableQuery(query) {
    let exportedRows = [];
    let sel = null;
    try {
        sel = db.prepare(query);
    } catch (ex) {
        if (sel != null) {
            sel.free();
        }
        showError(ex);
        setIsLoading(false);
        return null;
    }

    const columnNames = sel.getColumnNames();

    exportedRows.push(...[columnNames]);
    while (sel.step()) {
        const rows = sel.get();
        exportedRows.push(...[rows]);
    }
    sel.free();
    return exportedRows;
}

function exportCsvTable(tableName) {
    return exportCsvTableQuery(`SELECT * FROM ${q(tableName)}`);
}

function exportAllToCsv() {
    setIsLoading(true);
    const zip = new JSZip();
    for (const tableName of loadedTableNames) {
        const exportedRows = exportCsvTable(tableName);
        if (exportedRows != null) {
            zip.file(tableName + ".csv", "\ufeff" + arrayToCsv(exportedRows));
        } else {
            setIsLoading(false);
            return;
        }
    }

    zip.generateAsync({type: "blob"})
        .then(function (content) {
            saveAs(content, "exported_all_db.zip");
        });
    setIsLoading(false);
}

function exportSelectedTableToCsv() {
    const tableName = $("#tables").val();
    if (!tableName) return;
    setIsLoading(true);

    const exportedRows = exportCsvTable(tableName);
    if (exportedRows != null) {
        const blob = new Blob(["\ufeff" + arrayToCsv(exportedRows)], {type: "text/plain;charset=utf-8"});
        saveAs(blob, "exported_" + tableName.toLowerCase() + "_db.csv");
    }

    setIsLoading(false);
}

function exportQueryTableToCsv() {
    setIsLoading(true);

    const query = editor.getValue();
    const exportedRows = exportCsvTableQuery(query);
    if (exportedRows != null) {
        const blob = new Blob(["\ufeff" + arrayToCsv(exportedRows)], {type: "text/plain;charset=utf-8"});
        saveAs(blob, "exported_" + (getTableNameFromQuery(query) || "query").toLowerCase() + "_db.csv");
    }

    setIsLoading(false);
}
